#include <iostream>
#include <random>
#include <vector>
#include <stdexcept>

std::vector<int> seleccionar(std::mt19937& motor,
                            const std::vector<int>& candidatos,
                            int cantidad) {
    if (candidatos.size() > 10 || cantidad < 0) {
        throw std::invalid_argument("Sélection invalide");
    }
    const int total = static_cast<int>(candidatos.size());
    if (cantidad > total) {
        throw std::invalid_argument("Sélection invalide");
    }
    for (int i = 0; i < total; ++i) {
        if (candidatos.at(i) < 0 || candidatos.at(i) > 9) {
            throw std::invalid_argument("Sélection invalide");
        }
        for (int anterior = 0; anterior < i; ++anterior) {
            if (candidatos.at(anterior) == candidatos.at(i)) {
                throw std::invalid_argument("Sélection invalide");
            }
        }
    }
    std::vector<int> resultado;
    if (cantidad == 0) {
        return resultado;
    }
    std::vector<int> trabajo = candidatos;
    int restantes = total;
    for (int extraidos = 0; extraidos < cantidad; ++extraidos) {
        std::uniform_int_distribution<int> indice{0, restantes - 1};
        const int posicion = indice(motor);
        const int elegido = trabajo.at(posicion);
        resultado.push_back(elegido);
        trabajo.at(posicion) = trabajo.at(restantes - 1);
        --restantes;
    }
    return resultado;
}

bool seleccion_correcta(const std::vector<int>& candidatos,
                        const std::vector<int>& elegidos, int cantidad) {
    if (cantidad < 0 || elegidos.size() > 10
        || static_cast<int>(elegidos.size()) != cantidad) {
        return false;
    }
    const int total = static_cast<int>(elegidos.size());
    for (int i = 0; i < total; ++i) {
        bool pertenece = false;
        for (int candidato : candidatos) {
            if (candidato == elegidos.at(i)) { pertenece = true; }
        }
        if (!pertenece) { return false; }
        for (int anterior = 0; anterior < i; ++anterior) {
            if (elegidos.at(anterior) == elegidos.at(i)) { return false; }
        }
    }
    return true;
}

int main() {
    const std::vector<int> candidatos{9, 4, 1, 7, 0};
    const std::vector<int> original = candidatos;
    std::mt19937 motor{733};
    std::mt19937 repeticion = motor;
    const std::vector<int> elegidos = seleccionar(motor, candidatos, 4);
    const std::vector<int> repetidos = seleccionar(repeticion, candidatos, 4);
    std::cout << "Quantité:" << elegidos.size() << '\n';
    std::cout << "Propriétés:" << seleccion_correcta(candidatos, elegidos, 4) << '\n';
    std::cout << "Original:" << (candidatos == original) << '\n';
    std::cout << "Reproduction:" << (elegidos == repetidos && motor == repeticion) << '\n';
    std::mt19937 continuacion = motor;
    const std::vector<int> segundo = seleccionar(motor, candidatos, 2);
    const std::vector<int> repetido = seleccionar(continuacion, candidatos, 2);
    std::cout << "Continuation:" << (segundo == repetido && motor == continuacion) << '\n';
    const std::mt19937 antes_vacio = motor;
    const std::vector<int> vacio = seleccionar(motor, candidatos, 0);
    std::cout << "Vide:" << vacio.size() << ':' << (motor == antes_vacio) << '\n';
    const std::mt19937 antes_error = motor;
    try {
        const std::vector<int> invalida = seleccionar(motor, {4, 4}, 0);
        std::cout << "Acceptée:" << invalida.size() << '\n';
    } catch (const std::invalid_argument&) {
        std::cout << "Rejet:" << (motor == antes_error) << '\n';
    }
    return 0;
}

