struct Pareja {
    int primero;
    int segundo;
};

std::vector<Pareja> formar_parejas(std::mt19937& motor,
                                 const std::vector<int>& candidatos,
                                 int pares) {
    if (pares < 0 || pares > 5 || candidatos.size() > 10) {
        throw std::invalid_argument("Paires invalides");
    }
    const int total = static_cast<int>(candidatos.size());
    if (pares > total / 2) {
        throw std::invalid_argument("Paires invalides");
    }
    const std::vector<int> elegidos = seleccionar(motor, candidatos, 2 * pares);
    std::vector<Pareja> resultado;
    for (int i = 0; i < pares; ++i) {
        resultado.push_back(Pareja{elegidos.at(2 * i), elegidos.at(2 * i + 1)});
    }
    return resultado;
}

std::vector<int> aplanar_parejas(const std::vector<Pareja>& grupos) {
    std::vector<int> resultado;
    for (const Pareja& grupo : grupos) {
        resultado.push_back(grupo.primero);
        resultado.push_back(grupo.segundo);
    }
    return resultado;
}

int main() {
    const std::vector<int> candidatos{7, 0, 9, 2, 5, 4, 1};
    const std::vector<int> original = candidatos;
    std::mt19937 motor{821};
    std::mt19937 referencia = motor;
    const std::vector<Pareja> grupos = formar_parejas(motor, candidatos, 3);
    const std::vector<int> planos = aplanar_parejas(grupos);
    const std::vector<int> orden = seleccionar(referencia, candidatos, 6);
    std::cout << "Paires:" << grupos.size() << '\n';
    std::cout << "Propriétés:" << (grupos.size() == 3
        && seleccion_correcta(candidatos, planos, 6)) << '\n';
    std::cout << "Ordre:" << (planos == orden && motor == referencia) << '\n';
    std::cout << "Original:" << (candidatos == original) << '\n';
    const std::mt19937 antes_vacio = motor;
    const std::vector<Pareja> vacio = formar_parejas(motor, candidatos, 0);
    std::cout << "Vide:" << vacio.size() << ':' << (motor == antes_vacio) << '\n';
    const std::mt19937 antes_error = motor;
    try {
        const std::vector<Pareja> demasiados = formar_parejas(motor, candidatos, 4);
        std::cout << "Acceptés:" << demasiados.size() << '\n';
    } catch (const std::invalid_argument&) {
        std::cout << "Rejet:" << (motor == antes_error) << '\n';
    }
    return 0;
}

