struct Pareja {
    int primero;
    int segundo;
};

int main() {
    const std::vector<Pareja> parejas{{4, 1}, {1, 8}};
    bool locales = true;
    std::vector<int> planos;
    for (const Pareja& pareja : parejas) {
        if (pareja.primero == pareja.segundo) { locales = false; }
        planos.push_back(pareja.primero);
        planos.push_back(pareja.segundo);
    }
    bool globales = true;
    for (int i = 0; i < 4; ++i) {
        for (int anterior = 0; anterior < i; ++anterior) {
            if (planos.at(anterior) == planos.at(i)) { globales = false; }
        }
    }
    std::cout << "Locales:" << locales << '\n';
    std::cout << "Globales:" << globales << '\n';
    return 0;
}
